-- public.next_material(p_world uuid, p_uid uuid, p_material text, p_bill jsonb, p_x integer, p_y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.next_material(p_world uuid, p_uid uuid, p_material text, p_bill jsonb, p_x integer, p_y integer)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select e.key from jsonb_each_text(p_bill) e
  left join build_material_bill b on b.material = p_material and b.item = e.key
  where e.value::int > 0
    -- Of the make the material takes it in, where it takes one (`bill_extra`): a garden bed's iron ribbons.
    and (pack_count(p_world, p_uid, e.key, b.extra) > 0 or site_count_of(p_world, p_x, p_y, e.key, b.extra) > 0
         -- And a Mason's Hod Carrier: the stores within its reach, for stone.
         or exists (select 1 from hod_stock(p_world, p_uid, e.key, build_reach(p_world, p_uid, p_material)) h
                     where item_of_make(h.id, b.extra)))
  order by coalesce(b.ord, 99), e.key limit 1
$function$
